/**
 * VTEX IO account workspace name
 *
 * @note Alphanumerical string beginning with lowercase letter and may contain `-` and/or `_`. Identifies a VTEX IO variant of an account/tenant.
 */
export declare const ATTR_VTEX_IO_WORKSPACE_NAME: "vtex_io.workspace.name";
